//! HIGHRES_IMU payloads must match the legacy-pinned MAVLink C library byte for byte.
//! Fixture: fixtures/telemetry/highres_imu.txt, regenerated by scripts/telemetry-oracle.py.
use flight_core::{Sensor, Tick, Vec3};
use flight_protocol::telemetry::highres_imu;

const FIXTURE: &str = include_str!("../../../fixtures/telemetry/highres_imu.txt");

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex byte"))
        .collect()
}

#[test]
fn highres_imu_matches_c_library() {
    let mut cases = 0;
    for line in FIXTURE.lines().filter(|l| !l.starts_with('#')) {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [t, values @ .., payload] = fields.as_slice() else {
            panic!("malformed line: {line}");
        };
        let v: Vec<f32> = values
            .iter()
            .map(|b| f32::from_bits(u32::from_str_radix(b, 16).expect("f32 bits")))
            .collect();
        let sensor = Sensor {
            at: Tick(t.parse().expect("time")),
            acceleration: Vec3(v[0], v[1], v[2]),
            gyro: Vec3(v[3], v[4], v[5]),
            calibrated: true,
        };
        assert_eq!(highres_imu(sensor).as_slice(), hex(payload), "case t={t}");
        cases += 1;
    }
    assert_eq!(cases, 6);
}

const STATUS_FIXTURE: &str = include_str!("../../../fixtures/telemetry/imu_saturated.txt");

#[test]
fn imu_saturated_statustext_matches_c_library_for_every_mask() {
    let mut cases = 0;
    for line in STATUS_FIXTURE.lines().filter(|l| !l.starts_with('#')) {
        let (mask, payload) = line.split_once(' ').expect("mask and payload");
        let mask = u8::from_str_radix(mask, 16).expect("mask");
        assert_eq!(
            flight_protocol::telemetry::imu_saturated(mask).as_slice(),
            hex(payload),
            "mask {mask:#04x}"
        );
        cases += 1;
    }
    assert_eq!(cases, 63);
}

#[test]
fn generic_statustext_matches_c_library() {
    // The saturation fixture is plain WARNING STATUSTEXT; the generic encoder used for
    // fault and denial notices (ADR 003 D3) must produce the same bytes.
    for line in STATUS_FIXTURE.lines().filter(|l| !l.starts_with('#')) {
        let (_, payload) = line.split_once(' ').expect("mask and payload");
        let bytes = hex(payload);
        let end = bytes[1..51].iter().position(|b| *b == 0).unwrap_or(50);
        let encoded = flight_protocol::telemetry::statustext(bytes[0], &bytes[1..1 + end]);
        assert_eq!(encoded.as_slice(), bytes);
    }
}
